Method.Implementation:
	set stat = $$$OK


 	set data.title = $ZCONVERT($ZSTRIP(data.title,  "<>WC"), "U")
 	// CORPPRV
 	if ( (data.sourceSystem = "CORPPRV") && ($FIND(data.title, ",") > 0) )
 	{
	 	set temp = data.title
	 	set data.suffix = $Piece(temp,",")
	 	set data.title = $Piece(temp,",",2)
 	}

    Quit stat
